'use strict';
const test = require('node:test');
const assert = require('node:assert');
const { paginate, totalPages } = require('./paginate.js');

test('page 1 returns perPage items', () => {
  assert.deepStrictEqual(paginate([1, 2, 3, 4, 5], 1, 2), [1, 2]);
});

test('page 2 continues where page 1 ended', () => {
  assert.deepStrictEqual(paginate([1, 2, 3, 4, 5], 2, 2), [3, 4]);
});

test('last page may be partial', () => {
  assert.deepStrictEqual(paginate([1, 2, 3, 4, 5], 3, 2), [5]);
});

test('totalPages rounds up', () => {
  assert.strictEqual(totalPages([1, 2, 3, 4, 5], 2), 3);
});

